export function loadTasks<T>(key: string, fallback: T, validate: (value: unknown) => value is T): T {
  try { const raw = localStorage.getItem(key); if (!raw) return fallback; const parsed: unknown = JSON.parse(raw); return validate(parsed) ? parsed : fallback; }
  catch { return fallback; }
}

