import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
export default defineConfig({plugins:[react()],test:{environment:"jsdom",globals:true,css:true}});

export type TaskStatus="todo"|"in-progress"|"done";
export type TaskPriority="low"|"medium"|"high";
export interface Task{id:string;title:string;description:string;status:TaskStatus;priority:TaskPriority;updatedAt:string}
export interface TaskDraft{title:string;description:string;status:TaskStatus;priority:TaskPriority}
export type StatusFilter=TaskStatus|"all";
export interface TaskFilters{query:string;status:StatusFilter}

import type {Task,TaskDraft,TaskFilters,TaskStatus} from "./types";
export const initialTasks:Task[]=[{id:"task-1",title:"Audit keyboard navigation",description:"Verify the primary workflow can be completed without a pointer.",status:"todo",priority:"high",updatedAt:"2026-09-05T09:00:00.000Z"},{id:"task-2",title:"Refactor filter state",description:"Keep the task list as the single source of truth and derive the visible list.",status:"in-progress",priority:"medium",updatedAt:"2026-09-06T10:30:00.000Z"},{id:"task-3",title:"Document release checklist",description:"Record build, test, accessibility and responsive smoke checks.",status:"done",priority:"low",updatedAt:"2026-09-06T15:45:00.000Z"}];
export function filterTasks(tasks:Task[],f:TaskFilters){const q=f.query.trim().toLowerCase();return tasks.filter(t=>(f.status==="all"||t.status===f.status)&&(q===""||`${t.title} ${t.description}`.toLowerCase().includes(q)))}
export function countByStatus(tasks:Task[],s:TaskStatus){return tasks.reduce((n,t)=>n+(t.status===s?1:0),0)}
export function isStatus(v:unknown):v is TaskStatus{return v==="todo"||v==="in-progress"||v==="done"}
export function isPriority(v:unknown):v is Task["priority"]{return v==="low"||v==="medium"||v==="high"}
export function isTask(v:unknown):v is Task{if(!v||typeof v!=="object")return false;const x=v as Record<string,unknown>;return typeof x.id==="string"&&typeof x.title==="string"&&typeof x.description==="string"&&isStatus(x.status)&&isPriority(x.priority)&&typeof x.updatedAt==="string"}
export function isTaskArray(v:unknown):v is Task[]{return Array.isArray(v)&&v.every(isTask)}
export function createId(){return typeof crypto!=="undefined"&&"randomUUID"in crypto?crypto.randomUUID():`task-${Date.now()}-${Math.random().toString(36).slice(2)}`}
export function normalizeDraft(d:TaskDraft):TaskDraft{return {...d,title:d.title.trim(),description:d.description.trim()}}
export function validateDraft(d:TaskDraft){const e:string[]=[];if(d.title.length<3)e.push("Title must be at least 3 characters.");if(d.title.length>120)e.push("Title must be 120 characters or fewer.");if(d.description.length<10)e.push("Description must be at least 10 characters.");if(d.description.length>500)e.push("Description must be 500 characters or fewer.");return e}

import {initialTasks,isTaskArray} from "../data";
import type {Task} from "../types";
const KEY="frontend-internship.issue-tracker.tasks";
export function loadTasks():{tasks:Task[];warning?:string}{try{const raw=localStorage.getItem(KEY);if(!raw)return{tasks:initialTasks};const parsed:unknown=JSON.parse(raw);if(!isTaskArray(parsed))return{tasks:initialTasks,warning:"Saved task data was invalid, so the starter data was restored."};return{tasks:parsed}}catch{return{tasks:initialTasks,warning:"Saved task data could not be read, so the starter data was restored."}}}
export function saveTasks(tasks:Task[]){try{localStorage.setItem(KEY,JSON.stringify(tasks));return{ok:true} as const}catch{return{ok:false,message:"Changes are visible now, but the browser could not save them locally."} as const}}

